{
  "roles": [
    "public body"
  ],
  "if": [
    "in commercial transactions between undertakings",
    "the creditor has fulfilled its contractual and legal obligations",
    "the creditor has not received the amount due on time"
  ],
  "then": "Member States shall ensure that the creditor is entitled to interest for late payment without the necessity of a reminder",
  "exceptions": [
    "the debtor is not responsible for the delay"
  ]
}
